import{_ as r,o as d,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"01 · 提案","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/01-proposal.md","filePath":"lab/shuangyu-fries/01-proposal.md","lastUpdated":1786327499000}'),s={name:"lab/shuangyu-fries/01-proposal.md"};function n(e,t,h,l,i,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="_01-·-提案" tabindex="-1">01 · 提案 <a class="header-anchor" href="#_01-·-提案" aria-label="Permalink to &quot;01 · 提案&quot;">​</a></h1><blockquote><p><strong>v1.0 对客版 · 可直接发送</strong> ｜ 2026-08-05</p><p>内部拍板记录见 <a href="./">项目首页</a>。本文不含任何内部链接与推演过程，可整份复制发出。</p></blockquote><hr><h2 id="薯条脆-·-双片提案" tabindex="-1">薯条脆 · 双片提案 <a class="header-anchor" href="#薯条脆-·-双片提案" aria-label="Permalink to &quot;薯条脆 · 双片提案&quot;">​</a></h2><p><strong>双宇食品「薯条脆」（46g 杯装 · 番茄味）｜ 广告片 ×2</strong></p><hr><h3 id="一、核心主张" tabindex="-1">一、核心主张 <a class="header-anchor" href="#一、核心主张" aria-label="Permalink to &quot;一、核心主张&quot;">​</a></h3><blockquote><p><strong>鲜切是原料，低温炸是工艺，脆是结果。</strong></p></blockquote><p>三者构成一条完整的因果链：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原薯鲜切          →      VF 低温油炸       →      脆，且是土豆本来的颜色</span></span>
<span class="line"><span>（原料 · 看得见）        （工艺 · 讲做法）        （结果 · 吃得到）</span></span></code></pre></div><p><strong>主标题落在「原薯鲜切」，VF 工艺作为支撑证据出现。</strong></p><h4 id="为什么这样安排" tabindex="-1">为什么这样安排 <a class="header-anchor" href="#为什么这样安排" aria-label="Permalink to &quot;为什么这样安排&quot;">​</a></h4><p>贵司提出希望突出 VF 工艺，我们建议保留这一内容，但调整它在片中的位置。三点理由：</p><table tabindex="0"><thead><tr><th>理由</th><th>说明</th></tr></thead><tbody><tr><td><strong>与包装一致</strong></td><td>现有包装主打「原薯鲜切」，未出现 VF 相关表述。若广告主打 VF，消费者购买后在包装上无法对应，会削弱可信度</td></tr><tr><td><strong>消费者能听懂</strong></td><td>「真空低温油炸」需要先科普再理解，十几秒的片子没有这个空间。「真土豆切的」不需要解释</td></tr><tr><td><strong>是一个可验证的承诺</strong></td><td>鲜切的对立面是薯粉压模成型，消费者吃得出差别。<strong>他能自己验证的承诺，比他需要相信的承诺更有力</strong></td></tr></tbody></table><p>VF 在这条链路里承担的功能是回答「鲜切之后为什么还能这么脆、颜色还这么自然」——<strong>它在这个位置上是有作用的，不是附加说明。</strong></p><hr><h3 id="二、两支片子的分工" tabindex="-1">二、两支片子的分工 <a class="header-anchor" href="#二、两支片子的分工" aria-label="Permalink to &quot;二、两支片子的分工&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>A 片 · 主片</strong></th><th><strong>B 片 · 开盖片</strong></th></tr></thead><tbody><tr><td><strong>时长</strong></td><td>15–20 秒</td><td>6–10 秒</td></tr><tr><td><strong>画幅</strong></td><td>16:9，另出竖版裁切</td><td>9:16 竖屏</td></tr><tr><td><strong>回答的问题</strong></td><td>为什么值得买</td><td>想吃</td></tr><tr><td><strong>结构</strong></td><td>鲜切 → 工艺 → 脆 → 产品</td><td>撕开 → 露出 → 咔嚓 → 产品</td></tr><tr><td><strong>建议投放</strong></td><td>电商详情页 / 品牌自媒体 / 线下屏</td><td>抖音 · 小红书信息流</td></tr><tr><td><strong>开头</strong></td><td>可用一秒铺垫</td><td>第一帧即为撕封口</td></tr><tr><td><strong>声音</strong></td><td>环境音为主，安静</td><td><strong>音效是主角</strong></td></tr></tbody></table><h4 id="b-片为什么围绕「撕开封口」" tabindex="-1">B 片为什么围绕「撕开封口」 <a class="header-anchor" href="#b-片为什么围绕「撕开封口」" aria-label="Permalink to &quot;B 片为什么围绕「撕开封口」&quot;">​</a></h4><p>袋装零食在广告里有一个长期难题：<strong>没有标志性动作。</strong>「倒出来」「抓一把」都不够干净，不足以撑起一支片子的开头。</p><p><strong>杯装解决了这个问题。</strong> 撕开铝箔封口是一个干净、有仪式感、且自带声音的动作——它是这个包装形态独有的资产。</p><p>另外，这个产品是常温预包装零食，<strong>没有热气</strong>。而热气是食欲镜头里最强的一条线索（热 = 刚做好 = 新鲜）。撕封口的动作加上开盖瞬间的声音，正好补上这部分缺失的信息量。</p><h4 id="素材复用" tabindex="-1">素材复用 <a class="header-anchor" href="#素材复用" aria-label="Permalink to &quot;素材复用&quot;">​</a></h4><p>断面透光、成品掉落两组镜头 A 片 B 片共用。<strong>先制作 A 片，B 片从中剪出</strong>，可显著压缩工作量。</p><hr><h3 id="三、内容边界" tabindex="-1">三、内容边界 <a class="header-anchor" href="#三、内容边界" aria-label="Permalink to &quot;三、内容边界&quot;">​</a></h3><p>食品广告 + 工艺宣称属于双重监管范畴。以下表述<strong>不会出现在成片中</strong>，请贵司知悉：</p><table tabindex="0"><thead><tr><th>不会出现</th><th>原因</th></tr></thead><tbody><tr><td>非油炸</td><td>VF 工艺属于油炸（真空环境下的低温油炸），成品含油。此为事实层面的问题</td></tr><tr><td>更健康 / 低脂 / 0 负担 / 无油</td><td>营养声称有国家标准规定的量化门槛，须产品实测达标并按规范标示后方可使用</td></tr><tr><td>吃了不长胖 / 适合减肥</td><td>属功效宣称，普通食品不得涉及</td></tr><tr><td>与传统油炸产品的直接对比</td><td>直接对比同类产品存在被认定为贬低同行的风险</td></tr><tr><td>含真番茄 / 真实果肉</td><td>需配料表支持后方可使用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关于对比结构</p><p>我们理解「左边传统、右边 VF」这类结构在传播上效果直接。但直接对比同类产品在广告法下有明确风险，<strong>这是合规判断，不是创意偏好</strong>，因此不纳入方案。</p><p><strong>替代做法</strong>：只呈现自身工艺，不出现任何参照物。对比在消费者脑中自行完成——而且他自己得出的对比，比屏幕上摆出来的更有说服力。</p></div><hr><h3 id="四、工期" tabindex="-1">四、工期 <a class="header-anchor" href="#四、工期" aria-label="Permalink to &quot;四、工期&quot;">​</a></h3><p>物料齐备后，两支片子合计 <strong>6 个工作日</strong>：</p><table tabindex="0"><thead><tr><th>阶段</th><th>工作日</th></tr></thead><tbody><tr><td>分镜设计 + 贵司确认</td><td>1</td></tr><tr><td>首轮制作（全片跑通一版）</td><td>1.5</td></tr><tr><td>单镜返工与优化</td><td>1.5</td></tr><tr><td>后期合成 · 调色 · 音效</td><td>1</td></tr><tr><td><strong>合规审校与改稿</strong></td><td><strong>1</strong></td></tr><tr><td>合计</td><td><strong>6</strong></td></tr></tbody></table><p><strong>不含</strong>：物料等待时间、贵司内部审批轮次。</p><div class="tip custom-block"><p class="custom-block-title">关于最后一天</p><p>合规审校不产出画面，但对工艺类食品广告是必需环节。<strong>把问题拦在成片之前，成本远低于成片之后返工。</strong></p></div><p>报价另附。</p><hr><h3 id="五、需要贵司确认的事项" tabindex="-1">五、需要贵司确认的事项 <a class="header-anchor" href="#五、需要贵司确认的事项" aria-label="Permalink to &quot;五、需要贵司确认的事项&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>事项</th><th>不确认的影响</th></tr></thead><tbody><tr><td>1</td><td>核心主张采用「原薯鲜切 + VF 支撑」是否认可</td><td>创意方向无法推进</td></tr><tr><td>2</td><td>包装日文副标「カリカリポテトフライ」是否对应真实的日本技术、合作或出口关系</td><td>见下方说明</td></tr><tr><td>3</td><td>两支片子的具体投放位与优先级</td><td>时长、画幅、开头节奏无法最终确定</td></tr><tr><td>4</td><td>交期与预算范围</td><td>排期无法确定</td></tr><tr><td>5</td><td>产品是否已上市、能否提供实物样品</td><td>影响部分镜头的制作方式</td></tr></tbody></table><h4 id="关于第-2-项" tabindex="-1">关于第 2 项 <a class="header-anchor" href="#关于第-2-项" aria-label="Permalink to &quot;关于第 2 项&quot;">​</a></h4><p>包装印制日文在行业内属常见做法，通常不构成问题。但<strong>广告中主动呈现日式调性或暗示进口属性，性质不同</strong>——若无真实对应关系，存在被认定为虚假宣传的风险。</p><p><strong>在贵司提供书面说明之前，我们将按「无日本背景」处理</strong>：片中不出现日式场景、日文字幕、日式配乐等元素。包装本身出镜时，其上的日文属客观呈现，不受影响。</p><hr><h3 id="六、制作方式说明" tabindex="-1">六、制作方式说明 <a class="header-anchor" href="#六、制作方式说明" aria-label="Permalink to &quot;六、制作方式说明&quot;">​</a></h3><p>为便于贵司理解排期与物料需求，以下说明部分镜头的制作方式：</p><table tabindex="0"><thead><tr><th>镜头</th><th>制作方式</th></tr></thead><tbody><tr><td><strong>包装出镜</strong></td><td><strong>必须使用实拍或设计源文件渲染。</strong> 包装含 logo、中文、日文与精确品牌色，生成式工具无法准确还原，此环节无替代方案</td></tr><tr><td><strong>撕开封口</strong></td><td>建议<strong>实拍</strong>。该动作涉及真实手部与不可逆形变，实拍的效率与质量均优于生成。需贵司提供实物样品</td></tr><tr><td>工艺过程 · 断面结构</td><td>生成制作。这类画面实拍难以实现（设备封闭、微观尺度），是生成技术的优势区间</td></tr><tr><td>成品质感镜头</td><td>生成制作</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">关于「哪些用 AI、哪些不用」</p><p>我们的原则是：<strong>生成技术不擅长的部分，不用生成技术做。</strong></p><p>真实手部动作、品牌文字、精确配色——这几类交给实拍或设计，成本更低、结果更可控。把生成能力用在实拍拍不到的地方（工艺内部、微观结构），才是它真正的价值所在。</p></div><hr><h3 id="七、物料需求" tabindex="-1">七、物料需求 <a class="header-anchor" href="#七、物料需求" aria-label="Permalink to &quot;七、物料需求&quot;">​</a></h3><p>详见随附的《物料清单》。其中三项为<strong>必须</strong>，缺失将直接影响交付：</p><ol><li>包装设计源文件（含刀版）</li><li>VF 工艺的书面资料</li><li>配料表与营养成分表</li></ol><hr><p><strong>双宇食品「薯条脆」双片提案 · v1.0 · 2026-08-05</strong></p>`,53)])])}const c=r(s,[["render",n]]);export{b as __pageData,c as default};
